// ── Backlight fade (dedicated FreeRTOS task) ─────────────────────────────
// blFadeTo() is safe to call from any context; the task moves the current
// brightness toward the target at 0.04 per tick (20 ms) → 500 ms full fade.
static volatile float s_blCurrent = 1.0f;
static volatile float s_blTarget  = 1.0f;

static void blFadeTo(float target) { s_blTarget = target; }

static void backlightTask(void* /*arg*/) {
    const TickType_t TICK = pdMS_TO_TICKS(20);
    const float      STEP = 1.0f / 25.0f;
    for (;;) {
        float cur = s_blCurrent;
        float tgt = s_blTarget;
        if (cur != tgt) {
            float delta = tgt - cur;
            float step  = (delta >  0.0f) ? ((delta <  STEP) ? delta :  STEP)
                                           : ((delta > -STEP) ? delta : -STEP);
            cur += step;
            if (cur < 0.0f) cur = 0.0f;
            if (cur > 1.0f) cur = 1.0f;
            s_blCurrent = cur;
            smartdisplay_lcd_set_backlight(cur);
        }
        vTaskDelay(TICK);
    }
}

