// Logo
// ═══════════════════════════════════════════════════════════════════════════
static uint16_t* s_logoBuf = nullptr;

static void placeLogoInStatusBar(lv_obj_t* scr) {
    if (!s_logoBuf) return;
    lv_obj_t* canvas = lv_canvas_create(scr);
    lv_canvas_set_buffer(canvas, s_logoBuf, LOGO_W, LOGO_H,
                         LV_COLOR_FORMAT_RGB565);
    lv_obj_set_size(canvas, LOGO_W, LOGO_H);
    lv_obj_align(canvas, LV_ALIGN_BOTTOM_RIGHT, -2, -2);
    lv_obj_clear_flag(canvas, LV_OBJ_FLAG_CLICKABLE);
}

static void showSplash(uint32_t ms) {
    s_logoBuf = (uint16_t*)malloc(LOGO_W * LOGO_H * 2);
    if (!s_logoBuf) { Serial.println("[logo] OOM"); return; }
    memcpy(s_logoBuf, LOGO_RGB565, LOGO_W * LOGO_H * 2);

    lv_obj_t* splash = lv_obj_create(NULL);
    lv_obj_remove_style_all(splash);
    lv_obj_set_style_bg_color(splash, lv_color_hex(C_BG),  LV_PART_MAIN);
    lv_obj_set_style_bg_opa (splash, LV_OPA_COVER,         LV_PART_MAIN);
    lv_obj_clear_flag(splash, (lv_obj_flag_t)(LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE));

    lv_obj_t* canvas = lv_canvas_create(splash);
    lv_canvas_set_buffer(canvas, s_logoBuf, LOGO_W, LOGO_H,
                         LV_COLOR_FORMAT_RGB565);
    lv_obj_set_size(canvas, LOGO_W, LOGO_H);
    lv_obj_align(canvas, LV_ALIGN_CENTER, 0, 0);
    lv_obj_clear_flag(canvas, LV_OBJ_FLAG_CLICKABLE);

    lv_screen_load(splash);

    uint32_t t0 = millis();
    uint32_t _last = millis();
    while (millis() - t0 < ms) {
        uint32_t _now = millis();
        lv_tick_inc(_now - _last);
        _last = _now;
        lv_task_handler(); delay(5);
    }

    // Load a blank screen and auto-delete splash — avoids deleting the active
    // screen while it is still the active screen, which leaves LVGL with a
    // dangling act_scr pointer and breaks the next lv_screen_load() call.
    lv_obj_t* blank = lv_obj_create(NULL);
    lv_screen_load_anim(blank, LV_SCR_LOAD_ANIM_NONE, 0, 0, /*auto_del=*/true);
    lv_tick_inc(5);
    lv_task_handler();   // commit the switch; splash is deleted here

    Serial.printf("[logo] splash %dx%d px (%d bytes)\n", LOGO_W, LOGO_H, LOGO_W * LOGO_H * 2);
}

// ═══════════════════════════════════════════════════════════════════════════
// Builder helpers
// ═══════════════════════════════════════════════════════════════════════════
static lv_obj_t* makeBtn(lv_obj_t* parent,
                          int x, int y, int w, int h,
                          const char* txt,
                          lv_event_cb_t cb, void* udata = nullptr,
                          lv_obj_t** outLbl = nullptr) {
    lv_obj_t* btn = lv_btn_create(parent);
    lv_obj_set_pos(btn, x, y);
    lv_obj_set_size(btn, w, h);
    lv_obj_set_style_bg_color(btn, lv_color_hex(C_BTN_OFF), LV_PART_MAIN);
    lv_obj_set_style_bg_color(btn, lv_color_hex(C_BTN_ON),  LV_STATE_PRESSED);
    lv_obj_set_style_radius(btn, 5, LV_PART_MAIN);
    lv_obj_set_style_border_width(btn, 0, LV_PART_MAIN);
    lv_obj_set_style_shadow_width(btn, 0, LV_PART_MAIN);
    if (cb) lv_obj_add_event_cb(btn, cb, LV_EVENT_CLICKED, udata);

    lv_obj_t* lbl = lv_label_create(btn);
    lv_label_set_text(lbl, txt);
    lv_obj_set_style_text_color(lbl, lv_color_white(), LV_PART_MAIN);
    lv_obj_set_style_text_font(lbl, &lv_font_montserrat_14, LV_PART_MAIN);
    lv_obj_center(lbl);
    if (outLbl) *outLbl = lbl;
    return btn;
}

