// ═══════════════════════════════════════════════════════════════════════════
// refreshControls — re-syncs button colours and visibility to current state
// ═══════════════════════════════════════════════════════════════════════════
static void refreshControls() {
    if (!s_heatOn || !s_roomSp || !s_waterSp || !s_fanMode) return;

    bool heat   = (s_heatOn->getIntValue() != 0);
    int  fanVal = s_fanMode->getIntValue();   // -1=eco, -2=high, 0=off, 1-10=numeric

    // ── Heating button ────────────────────────────────────────────────────
    if (s_heatBtnLbl)
        lv_label_set_text(s_heatBtnLbl, heat ? t(TK::HEAT_ON) : t(TK::HEAT_OFF));
    if (s_heatBtn)
        lv_obj_set_style_bg_color(s_heatBtn,
            lv_color_hex(heat ? C_HEAT_ON : C_BTN_OFF), LV_PART_MAIN);

    // ── Temperature setpoint ─────────────────────────────────────────────
    if (s_spRow) {
        if (heat) {
            lv_obj_remove_flag(s_spRow, LV_OBJ_FLAG_HIDDEN);
            if (s_spLbl) {
                char buf[12];
                snprintf(buf, sizeof(buf), "%.1f\xc2\xb0""C", s_roomSp->getFloatValue());
                lv_label_set_text(s_spLbl, buf);
            }
        } else {
            lv_obj_add_flag(s_spRow, LV_OBJ_FLAG_HIDDEN);
        }
    }

    // ── Fan ───────────────────────────────────────────────────────────────
    if (heat) {
        if (s_fanHeatingRow) lv_obj_remove_flag(s_fanHeatingRow, LV_OBJ_FLAG_HIDDEN);
        if (s_fanOffRow)     lv_obj_add_flag(s_fanOffRow,   LV_OBJ_FLAG_HIDDEN);
        if (s_fanLevelRow)   lv_obj_add_flag(s_fanLevelRow, LV_OBJ_FLAG_HIDDEN);

        String fanStr = s_fanMode->getStringValue();
        for (int i = 0; i < FAN_HEAT_N; i++) {
            if (s_fanBtn[i])
                lv_obj_set_style_bg_color(s_fanBtn[i],
                    lv_color_hex((fanStr == FAN_STR[i]) ? C_BTN_ON : C_BTN_OFF),
                    LV_PART_MAIN);
        }
    } else {
        if (s_fanHeatingRow) lv_obj_add_flag(s_fanHeatingRow, LV_OBJ_FLAG_HIDDEN);
        if (s_fanOffRow)     lv_obj_remove_flag(s_fanOffRow,  LV_OBJ_FLAG_HIDDEN);

        bool fanOn       = (fanVal != 0);
        bool boilerActive = (s_waterSp && s_waterSp->getStringValue() != "off");

        if (fanVal > 0) s_fanLevel = fanVal;

        // Show level row only when fan is on and boiler is idle
        if (s_fanLevelRow) {
            if (fanOn && !boilerActive) lv_obj_remove_flag(s_fanLevelRow, LV_OBJ_FLAG_HIDDEN);
            else                        lv_obj_add_flag   (s_fanLevelRow, LV_OBJ_FLAG_HIDDEN);
        }

        // Disable fan On/Off when the boiler is active (Truma ignores fan commands while boiling)
        if (s_fanOnBtn && s_fanOffBtn) {
            if (boilerActive) {
                lv_obj_add_state(s_fanOnBtn,  LV_STATE_DISABLED);
                lv_obj_add_state(s_fanOffBtn, LV_STATE_DISABLED);
            } else {
                lv_obj_remove_state(s_fanOnBtn,  LV_STATE_DISABLED);
                lv_obj_remove_state(s_fanOffBtn, LV_STATE_DISABLED);
            }
            lv_obj_set_style_bg_color(s_fanOnBtn,
                lv_color_hex(fanOn  ? C_BTN_ON : C_BTN_OFF), LV_PART_MAIN);
            lv_obj_set_style_bg_color(s_fanOffBtn,
                lv_color_hex(!fanOn ? C_BTN_ON : C_BTN_OFF), LV_PART_MAIN);
        }

        if (s_fanLevelLbl) {
            char buf[4];
            snprintf(buf, sizeof(buf), "%d", s_fanLevel);
            lv_label_set_text(s_fanLevelLbl, buf);
        }
    }

    // ── Boiler / Hot water ───────────────────────────────────────────────
    String boiler = s_waterSp->getStringValue();
    for (int i = 0; i < BOILER_N; i++) {
        if (s_boilerBtn[i])
            lv_obj_set_style_bg_color(s_boilerBtn[i],
                lv_color_hex((boiler == BOILER_STR[i]) ? C_BTN_ON : C_BTN_OFF),
                LV_PART_MAIN);
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// Callbacks
// ═══════════════════════════════════════════════════════════════════════════
static void heatCb(lv_event_t*) {
    if (!s_heatOn) return;
    bool turningOff = (s_heatOn->getIntValue() != 0);
    s_heatOn->setValue(String(turningOff ? "0" : "1"));
    if (turningOff && s_fanMode) s_fanMode->setValue(String("off"));
    refreshControls();
}

static void spDownCb(lv_event_t*) {
    if (!s_roomSp) return;
    double v = s_roomSp->getFloatValue() - 0.5;
    if (v >= 5.0) s_roomSp->setValue(v);
    refreshControls();
}

static void spUpCb(lv_event_t*) {
    if (!s_roomSp) return;
    double v = s_roomSp->getFloatValue() + 0.5;
    if (v <= 30.0) s_roomSp->setValue(v);
    refreshControls();
}

static void boilerCb(lv_event_t* e) {
    if (!s_waterSp) return;
    int idx = (int)(intptr_t)lv_event_get_user_data(e);
    // When activating the boiler, pre-emptively set fan to off. The Truma applies
    // any pending fan command when it cycles, which could cause unexpected fan starts.
    if (idx != 0 && s_fanMode) s_fanMode->setValue(String("off"));
    s_waterSp->setValue(String(BOILER_STR[idx]));
    refreshControls();
}

static void fanHeatCb(lv_event_t* e) {
    if (!s_fanMode) return;
    int idx = (int)(intptr_t)lv_event_get_user_data(e);
    s_fanMode->setValue(String(FAN_STR[idx]));
    refreshControls();
}

static void fanOnCb(lv_event_t*) {
    if (!s_fanMode) return;
    if (s_waterSp && s_waterSp->getStringValue() != "off") return;  // boiler active
    s_fanMode->setValue(String(s_fanLevel));
    refreshControls();
}

static void fanOffCb(lv_event_t*) {
    if (!s_fanMode) return;
    if (s_waterSp && s_waterSp->getStringValue() != "off") return;  // boiler active
    s_fanMode->setValue(String("off"));
    refreshControls();
}

static void fanLevelDownCb(lv_event_t*) {
    if (!s_fanMode) return;
    if (s_waterSp && s_waterSp->getStringValue() != "off") return;  // boiler active
    if (s_fanLevel > 1) {
        s_fanLevel--;
        if (s_fanMode->getIntValue() > 0) s_fanMode->setValue(String(s_fanLevel));
        refreshControls();
    }
}

static void fanLevelUpCb(lv_event_t*) {
    if (!s_fanMode) return;
    if (s_waterSp && s_waterSp->getStringValue() != "off") return;  // boiler active
    if (s_fanLevel < 10) {
        s_fanLevel++;
        if (s_fanMode->getIntValue() > 0) s_fanMode->setValue(String(s_fanLevel));
        refreshControls();
    }
}

static void energyDdCb(lv_event_t* e) {
    lv_obj_t* dd = (lv_obj_t*)lv_event_get_target(e);
    s_energyMode = (int)lv_dropdown_get_selected(dd);
}

// ═══════════════════════════════════════════════════════════════════════════
// Public API: energy mode (read by main.cpp each loop iteration)
// ═══════════════════════════════════════════════════════════════════════════
int cydGetEnergyMode() { return s_energyMode; }

void cydSetEnergyIdx(int idx) {
    if (idx < 0 || idx > 4) return;
    s_energyMode = idx;
    if (s_energyDd) lv_dropdown_set_selected(s_energyDd, (uint16_t)idx);
}

// ═══════════════════════════════════════════════════════════════════════════
// NVS — screen-off timeout
// ═══════════════════════════════════════════════════════════════════════════
static void loadTimeoutIdx() {
    Preferences p;
    p.begin("cyd", true);
    s_timeoutIdx = p.getInt("timeout_idx", 0);
    p.end();
}
static void saveTimeoutIdx() {
    Preferences p;
    p.begin("cyd", false);
    p.putInt("timeout_idx", s_timeoutIdx);
    p.end();
}

// ═══════════════════════════════════════════════════════════════════════════
// Wake-on-touch overlay  (lives on lv_layer_top, above every screen)
// ═══════════════════════════════════════════════════════════════════════════
static void wakeCb(lv_event_t*) {
    if (!s_screenOff) return;
    blFadeTo(1.0f);
    s_screenOff = false;
    if (s_wakeOverlay) { lv_obj_delete(s_wakeOverlay); s_wakeOverlay = nullptr; }
}

// ═══════════════════════════════════════════════════════════════════════════
// Display settings screen
// ═══════════════════════════════════════════════════════════════════════════
static void refreshDisplayOpts() {
    for (int i = 0; i < TIMEOUT_N; i++) {
        if (s_dispOptBtn[i])
            lv_obj_set_style_bg_color(s_dispOptBtn[i],
                lv_color_hex(i == s_timeoutIdx ? C_BTN_ON : C_BTN_OFF),
                LV_PART_MAIN);
    }
}

static void navigateBackFromDisplay() {
    lv_obj_t* old = s_displayScr;
    s_displayScr  = nullptr;
    for (int i = 0; i < TIMEOUT_N; i++) s_dispOptBtn[i] = nullptr;
    lv_screen_load(s_scr);
    if (old) lv_obj_delete(old);
    showSettingsMenu();
}

static void dispOptCb(lv_event_t* e) {
    s_timeoutIdx = (int)(intptr_t)lv_event_get_user_data(e);
    saveTimeoutIdx();
    navigateBackFromDisplay();
}

static void dispBackCb(lv_event_t*) { navigateBackFromDisplay(); }

static void showDisplaySettings() {
    if (s_displayScr) return;

    lv_obj_t* scr = lv_obj_create(NULL);
    lv_obj_remove_style_all(scr);
    lv_obj_set_style_bg_color(scr, lv_color_hex(C_BG), LV_PART_MAIN);
    lv_obj_set_style_bg_opa (scr, LV_OPA_COVER,        LV_PART_MAIN);
    lv_obj_clear_flag(scr, (lv_obj_flag_t)LV_OBJ_FLAG_SCROLLABLE);
    s_displayScr = scr;

    lv_obj_t* topBar = lv_obj_create(scr);
    lv_obj_remove_style_all(topBar);
    lv_obj_set_pos(topBar, 0, 0);
    lv_obj_set_size(topBar, 320, Y_TOP_H);
    lv_obj_set_style_bg_color(topBar, lv_color_hex(C_TOPBAR), LV_PART_MAIN);
    lv_obj_set_style_bg_opa (topBar, LV_OPA_COVER,             LV_PART_MAIN);
    lv_obj_clear_flag(topBar, (lv_obj_flag_t)(LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE));

    lv_obj_t* backBtn = makeBtn(topBar, 2, 2, 70, 24,
                                symText(LV_SYMBOL_LEFT, TK::BACK), dispBackCb);
    lv_obj_set_style_bg_color(backBtn, lv_color_hex(C_TOPBAR), LV_PART_MAIN);

    lv_obj_t* ttl = lv_label_create(topBar);
    lv_obj_set_style_text_font(ttl, &lv_font_montserrat_14, LV_PART_MAIN);
    lv_obj_set_style_text_color(ttl, lv_color_white(), LV_PART_MAIN);
    lv_label_set_text(ttl, t(TK::DISPLAY_TITLE));
    lv_obj_align(ttl, LV_ALIGN_CENTER, 0, 0);

    makeSep(scr, 0, Y_SEP1, 320, 1);
    makeSecLabel(scr, 8, Y_CONT + 4, t(TK::TIMEOUT_LABEL));

    const int bx = 8, bw = 304, bh = 34, bgap = 4;
    int by = Y_CONT + 24;
    for (int i = 0; i < TIMEOUT_N; i++) {
        s_dispOptBtn[i] = makeBtn(scr, bx, by, bw, bh,
                                   t(TIMEOUT_TK[i]), dispOptCb,
                                   (void*)(intptr_t)i);
        by += bh + bgap;
    }
    refreshDisplayOpts();
    lv_screen_load(scr);
}

// ═══════════════════════════════════════════════════════════════════════════
// Language selection screen (blocking busy-wait)
// ═══════════════════════════════════════════════════════════════════════════
static volatile int s_langSelected = -1;   // -1 = no selection yet
static void langEnCb(lv_event_t*) { s_langSelected = (int)Language::EN; }
static void langEsCb(lv_event_t*) { s_langSelected = (int)Language::ES; }

static void showLangSelectBlocking() {
    s_langSelected = -1;

    lv_obj_t* scr = lv_obj_create(NULL);
    lv_obj_remove_style_all(scr);
    lv_obj_set_style_bg_color(scr, lv_color_hex(C_BG), LV_PART_MAIN);
    lv_obj_set_style_bg_opa (scr, LV_OPA_COVER,        LV_PART_MAIN);
    lv_obj_clear_flag(scr, (lv_obj_flag_t)(LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE));

    lv_obj_t* title = lv_label_create(scr);
    lv_label_set_text(title, "TruMinus");
    lv_obj_set_style_text_font(title, &lv_font_montserrat_20, LV_PART_MAIN);
    lv_obj_set_style_text_color(title, lv_color_white(), LV_PART_MAIN);
    lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 38);

    lv_obj_t* sub = lv_label_create(scr);
    lv_label_set_text(sub, "Select language / Selecciona idioma");
    lv_obj_set_style_text_font(sub, &lv_font_montserrat_14, LV_PART_MAIN);
    lv_obj_set_style_text_color(sub, lv_color_hex(C_LABEL), LV_PART_MAIN);
    lv_obj_align(sub, LV_ALIGN_TOP_MID, 0, 74);

    // Two large buttons centred on screen
    makeBtn(scr, 20,  130, 130, 60, "English", langEnCb);
    makeBtn(scr, 170, 130, 130, 60, "Espanol", langEsCb);

    lv_screen_load(scr);
    lv_refr_now(lv_display_get_default());   // force immediate render — flush state may be stale after splash

    uint32_t _tickLast = millis();
    while (s_langSelected == -1) {
        uint32_t _tickNow = millis();
        lv_tick_inc(_tickNow - _tickLast);
        _tickLast = _tickNow;
        lv_task_handler(); delay(5);
    }

    setLanguage((Language)s_langSelected);
    lv_obj_delete(scr);
}

void cydShowLangSelect() { showLangSelectBlocking(); }

// ═══════════════════════════════════════════════════════════════════════════
// Main settings menu
// ═══════════════════════════════════════════════════════════════════════════
static void settingsBackCb(lv_event_t*) {
    lv_obj_t* old = s_settingsScr;
    s_settingsScr = nullptr;
    lv_screen_load(s_scr);
    if (old) lv_obj_delete(old);
}

static void wifiConfigCb(lv_event_t*) {
    lv_obj_t* old = s_settingsScr;
    s_settingsScr = nullptr;
    s_navRequest  = CydNavRequest::WifiSetup;
    lv_screen_load(s_scr);
    if (old) lv_obj_delete(old);
}

static void displayConfigCb(lv_event_t*) {
    lv_obj_t* old = s_settingsScr;
    s_settingsScr = nullptr;
    // Free settings-screen pool memory before allocating the display-settings screen.
    // Both screens coexisting briefly can exhaust the LVGL pool and silently break
    // touch callbacks on the new screen.
    lv_screen_load(s_scr);
    if (old) lv_obj_delete(old);
    showDisplaySettings();
}

static void langConfigCb(lv_event_t*) {
    lv_obj_t* old = s_settingsScr;
    s_settingsScr = nullptr;
    s_navRequest  = CydNavRequest::LangChange;
    lv_screen_load(s_scr);
    if (old) lv_obj_delete(old);
}

static void solarConfigCb(lv_event_t*) {
    lv_obj_t* old = s_settingsScr;
    s_settingsScr = nullptr;
    s_navRequest  = CydNavRequest::SolarSetup;
    lv_screen_load(s_scr);
    if (old) lv_obj_delete(old);
}

static void showSettingsMenu() {
    if (s_settingsScr) return;

    lv_obj_t* scr = lv_obj_create(NULL);
    lv_obj_remove_style_all(scr);
    lv_obj_set_style_bg_color(scr, lv_color_hex(C_BG), LV_PART_MAIN);
    lv_obj_set_style_bg_opa (scr, LV_OPA_COVER,        LV_PART_MAIN);
    lv_obj_clear_flag(scr, (lv_obj_flag_t)LV_OBJ_FLAG_SCROLLABLE);
    s_settingsScr = scr;

    lv_obj_t* topBar = lv_obj_create(scr);
    lv_obj_remove_style_all(topBar);
    lv_obj_set_pos(topBar, 0, 0);
    lv_obj_set_size(topBar, 320, Y_TOP_H);
    lv_obj_set_style_bg_color(topBar, lv_color_hex(C_TOPBAR), LV_PART_MAIN);
    lv_obj_set_style_bg_opa (topBar, LV_OPA_COVER,             LV_PART_MAIN);
    lv_obj_clear_flag(topBar, (lv_obj_flag_t)(LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE));

    lv_obj_t* backBtn = makeBtn(topBar, 2, 2, 70, 24,
                                symText(LV_SYMBOL_LEFT, TK::BACK), settingsBackCb);
    lv_obj_set_style_bg_color(backBtn, lv_color_hex(C_TOPBAR), LV_PART_MAIN);

    lv_obj_t* ttl = lv_label_create(topBar);
    lv_obj_set_style_text_font(ttl, &lv_font_montserrat_14, LV_PART_MAIN);
    lv_obj_set_style_text_color(ttl, lv_color_white(), LV_PART_MAIN);
    lv_label_set_text(ttl, t(TK::SETTINGS));
    lv_obj_align(ttl, LV_ALIGN_CENTER, 0, 0);

    makeSep(scr, 0, Y_SEP1, 320, 1);

    // 5 buttons: bh=34, bgap=5 → 5×34+4×5=190 px (screen is 240, top bar=28 → 202 px avail)
    const int bx = 8, bw = 304, bh = 34, bgap = 5;
    int by = Y_CONT + 6;

    makeBtn(scr, bx, by,               bw, bh,
            symText(LV_SYMBOL_WIFI,     TK::WIFI_CFG),  wifiConfigCb);
    makeBtn(scr, bx, by +   (bh+bgap), bw, bh,
            symText(LV_SYMBOL_SETTINGS, TK::DISP_CFG),  displayConfigCb);
    makeBtn(scr, bx, by + 2*(bh+bgap), bw, bh,
            symText(LV_SYMBOL_KEYBOARD, TK::LANGUAGE),  langConfigCb);
    makeBtn(scr, bx, by + 3*(bh+bgap), bw, bh,
            symText(LV_SYMBOL_CHARGE,   TK::SOLAR_CFG), solarConfigCb);

    lv_screen_load(scr);
}

static void gearCb(lv_event_t*) { showSettingsMenu(); }

void cydOpenSettingsMenu() { showSettingsMenu(); }

