CydNavRequest cydGetNavRequest()   { return s_navRequest; }
void          cydClearNavRequest() { s_navRequest = CydNavRequest::None; }

void cydReloadScreen() {
    if (s_wakeOverlay) { lv_obj_delete(s_wakeOverlay); s_wakeOverlay = nullptr; }
    s_screenOff = false;
    blFadeTo(1.0f);
    if (s_scr) lv_screen_load(s_scr);
}

// ═══════════════════════════════════════════════════════════════════════════
// Error modal
// ═══════════════════════════════════════════════════════════════════════════
static void errModalOkCb(lv_event_t*) {
    if (s_errorModal) { lv_obj_delete(s_errorModal); s_errorModal = nullptr; }
    s_errAcked = true;
}

static void showErrorModal(uint8_t cls, uint8_t code) {
    if (s_errorModal) { lv_obj_delete(s_errorModal); s_errorModal = nullptr; }

    uint32_t    col;
    TK          lblKey;
    if (cls == 1 || cls == 2) { col = C_WARN;       lblKey = TK::WARN_LBL;   }
    else if (cls == 40)        { col = C_ERR_LOCKED; lblKey = TK::LOCKED_LBL; }
    else                       { col = C_WIFI_NO;    lblKey = TK::ERROR_LBL;  }

    // Semi-transparent overlay on s_scr (on top due to creation order)
    s_errorModal = lv_obj_create(s_scr);
    lv_obj_remove_style_all(s_errorModal);
    lv_obj_set_pos(s_errorModal, 0, 0);
    lv_obj_set_size(s_errorModal, 320, 240);
    lv_obj_set_style_bg_color(s_errorModal, lv_color_hex(0x000000), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(s_errorModal, LV_OPA_70, LV_PART_MAIN);
    lv_obj_clear_flag(s_errorModal, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t* box = lv_obj_create(s_errorModal);
    lv_obj_set_size(box, 240, 110);
    lv_obj_align(box, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_color(box, lv_color_hex(C_TOPBAR), LV_PART_MAIN);
    lv_obj_set_style_border_color(box, lv_color_hex(col), LV_PART_MAIN);
    lv_obj_set_style_border_width(box, 1, LV_PART_MAIN);
    lv_obj_set_style_radius(box, 6, LV_PART_MAIN);
    lv_obj_set_style_pad_all(box, 8, LV_PART_MAIN);
    lv_obj_clear_flag(box, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t* title = lv_label_create(box);
    lv_label_set_text(title, t(lblKey));
    lv_obj_set_style_text_color(title, lv_color_hex(col), LV_PART_MAIN);
    lv_obj_set_style_text_font(title, &lv_font_montserrat_14, LV_PART_MAIN);
    lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 0);

    char sub[40];
    snprintf(sub, sizeof(sub), t(TK::ERR_SUBTITLE_FMT), cls, code);
    lv_obj_t* sublbl = lv_label_create(box);
    lv_label_set_text(sublbl, sub);
    lv_obj_set_style_text_color(sublbl, lv_color_hex(C_LABEL), LV_PART_MAIN);
    lv_obj_set_style_text_font(sublbl, &lv_font_montserrat_14, LV_PART_MAIN);
    lv_obj_align(sublbl, LV_ALIGN_TOP_MID, 0, 22);

    lv_obj_t* btn = makeBtn(box, 0, 0, 100, 32, t(TK::ACCEPT), errModalOkCb);
    lv_obj_align(btn, LV_ALIGN_BOTTOM_MID, 0, 0);
}

// ═══════════════════════════════════════════════════════════════════════════
// buildMainUI — creates all widgets as children of s_scr
// Separated from cydDisplayInit so it can be called again by cydRebuildUI().
// ═══════════════════════════════════════════════════════════════════════════
static void buildMainUI() {
    // ── Top bar ───────────────────────────────────────────────────────────
    lv_obj_t* topBar = lv_obj_create(s_scr);
    lv_obj_remove_style_all(topBar);
    lv_obj_set_pos(topBar, 0, 0);
    lv_obj_set_size(topBar, 320, Y_TOP_H);
    lv_obj_set_style_bg_color(topBar, lv_color_hex(C_TOPBAR), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(topBar, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_clear_flag(topBar, (lv_obj_flag_t)(LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE));

    // Tint icon (left) — blinks when boiler is heating
    s_aguaLbl = lv_label_create(topBar);
    lv_obj_set_style_text_font(s_aguaLbl, &symbols_14, LV_PART_MAIN);
    lv_obj_set_style_text_color(s_aguaLbl, lv_color_hex(0xaaccff), LV_PART_MAIN);
    lv_obj_set_style_text_opa(s_aguaLbl, LV_OPA_20, LV_PART_MAIN);
    lv_label_set_text(s_aguaLbl, MY_SYMBOL_TINT);
    lv_obj_set_pos(s_aguaLbl, 5, 7);

    // Flame icon — blinks when heating is active and demanding
    s_fireLbl = lv_label_create(topBar);
    lv_obj_set_style_text_font(s_fireLbl, &symbols_14, LV_PART_MAIN);
    lv_obj_set_style_text_color(s_fireLbl, lv_color_hex(0xaaccff), LV_PART_MAIN);
    lv_obj_set_style_text_opa(s_fireLbl, LV_OPA_20, LV_PART_MAIN);
    lv_label_set_text(s_fireLbl, MY_SYMBOL_FIRE);
    lv_obj_set_pos(s_fireLbl, 22, 7);

    // Indoor temperature
    s_ambLbl = lv_label_create(topBar);
    lv_obj_set_style_text_font(s_ambLbl, &symbols_14, LV_PART_MAIN);
    lv_obj_set_style_text_color(s_ambLbl, lv_color_hex(0xaaccff), LV_PART_MAIN);
    lv_label_set_text(s_ambLbl, MY_SYMBOL_THERMOMETER " -- \xc2\xb0""C");
    lv_obj_set_pos(s_ambLbl, 44, 7);

    // Outdoor temperature (AM2301 on P3 IO22)
    s_extLbl = lv_label_create(topBar);
    lv_obj_set_style_text_font(s_extLbl, &symbols_14, LV_PART_MAIN);
    lv_obj_set_style_text_color(s_extLbl, lv_color_hex(0xffcc88), LV_PART_MAIN);
    lv_label_set_text(s_extLbl, MY_SYMBOL_THERM_EXT " " MY_SYMBOL_CHEVRON_R " --\xc2\xb0""C");
    lv_obj_set_pos(s_extLbl, 117, 7);
    lv_obj_clear_flag(s_extLbl, LV_OBJ_FLAG_CLICKABLE);

    auto makeStatusIcon = [&](int x, const char* sym, uint32_t col) -> lv_obj_t* {
        lv_obj_t* lbl = lv_label_create(topBar);
        lv_obj_set_style_text_font(lbl, &lv_font_montserrat_14, LV_PART_MAIN);
        lv_obj_set_style_text_color(lbl, lv_color_hex(col), LV_PART_MAIN);
        lv_label_set_text(lbl, sym);
        lv_obj_set_pos(lbl, x, 6);
        lv_obj_clear_flag(lbl, LV_OBJ_FLAG_CLICKABLE);
        return lbl;
    };

    // Config button: centered between outdoor temp (~x=180) and WiFi icon (x=272)
    {
        char buf[24];
        snprintf(buf, sizeof(buf), "%s %s", LV_SYMBOL_SETTINGS, t(TK::CONF));
        lv_obj_t* confBtn = makeBtn(topBar, 186, 4, 72, 20, buf, gearCb);
        lv_obj_set_style_bg_color(confBtn, lv_color_hex(C_BTN_OFF), LV_PART_MAIN);
        lv_obj_set_style_bg_color(confBtn, lv_color_hex(C_BTN_ON), LV_STATE_PRESSED);
        lv_obj_set_style_text_color(lv_obj_get_child(confBtn, 0), lv_color_white(), LV_PART_MAIN);
    }

    s_wifiDot = makeStatusIcon(272, LV_SYMBOL_WIFI,    C_WIFI_NO);
    s_linDot  = makeStatusIcon(296, LV_SYMBOL_SHUFFLE, C_WIFI_NO);

    // ── Separators ───────────────────────────────────────────────────────
    makeSep(s_scr, 0,     Y_SEP1, 320, 1);    // horizontal top
    makeSep(s_scr, X_DIV, Y_CONT, 1, CONT_H); // vertical (x=153)
    makeSep(s_scr, 0,     Y_SEP2, 320, 1);    // horizontal bottom

    // ════════════════════════════════════════════════════════════════════
    // LEFT PANEL — HEATING
    // Content width: W_L - 8 = 146 px  (4 px margin on each side)
    // ════════════════════════════════════════════════════════════════════
    const int lx = 4;
    const int lw = W_L - 8;   // 146 px

    makeSecLabel(s_scr, lx, Y_CONT + 2, t(TK::HEATING));

    s_heatBtn = makeBtn(s_scr, lx, Y_CONT + 20, lw, 36,
                        t(TK::HEAT_OFF), heatCb, nullptr, &s_heatBtnLbl);
    lv_obj_set_style_text_font(s_heatBtnLbl, &lv_font_montserrat_14, LV_PART_MAIN);

    // Setpoint row (hidden when heating is OFF)
    s_spRow = makeRow(s_scr, lx, Y_CONT + 62, lw, 35);
    lv_obj_add_flag(s_spRow, LV_OBJ_FLAG_HIDDEN);

    makeBtn(s_spRow, 0, 0, 36, 35, LV_SYMBOL_DOWN, spDownCb);

    s_spLbl = lv_label_create(s_spRow);
    lv_obj_set_style_text_font(s_spLbl, &lv_font_montserrat_20, LV_PART_MAIN);
    lv_obj_set_style_text_color(s_spLbl, lv_color_white(), LV_PART_MAIN);
    lv_obj_set_style_text_align(s_spLbl, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
    lv_obj_set_size(s_spLbl, 70, 35);
    lv_obj_set_pos(s_spLbl, 38, 10);
    lv_label_set_text(s_spLbl, "20.0\xc2\xb0""C");

    makeBtn(s_spRow, lw - 36, 0, 36, 35, LV_SYMBOL_UP, spUpCb);

    // ── Fan section ───────────────────────────────────────────────────────
    makeSecLabel(s_scr, lx, Y_CONT + 99, t(TK::FAN));

    // Heating mode row: Eco | High  (no Off button, visible when heat ON)
    // 146 px: 2×71 + 1×4 gap = 146 px
    const int fwh = (lw - 4) / 2;   // ≈ 71 px
    s_fanHeatingRow = makeRow(s_scr, lx, Y_CONT + 115, lw, 28);
    for (int i = 0; i < FAN_HEAT_N; i++) {
        s_fanBtn[i] = makeBtn(s_fanHeatingRow, i * (fwh + 4), 0, fwh, 28,
                               fanHeatLabel(i), fanHeatCb, (void*)(intptr_t)i);
    }

    // Standby mode row: Off | On  (visible when heat OFF)
    // 146 px: 2×68 + 10 gap = 146 px
    const int fwo = (lw - 10) / 2;   // 68 px
    s_fanOffRow = makeRow(s_scr, lx, Y_CONT + 115, lw, 28);
    lv_obj_add_flag(s_fanOffRow, LV_OBJ_FLAG_HIDDEN);
    s_fanOffBtn = makeBtn(s_fanOffRow, 0,        0, fwo, 28, t(TK::OFF), fanOffCb);
    s_fanOnBtn  = makeBtn(s_fanOffRow, fwo + 10, 0, fwo, 28, t(TK::ON),  fanOnCb);

    // Level row: ↓ | N | ↑  (visible when heat OFF and fan On)
    // 146 px: 36 + 2 + 70 + 2 + 36 = 146 px
    s_fanLevelRow = makeRow(s_scr, lx, Y_CONT + 144, lw, 28);
    lv_obj_add_flag(s_fanLevelRow, LV_OBJ_FLAG_HIDDEN);
    makeBtn(s_fanLevelRow, 0, 0, 36, 28, LV_SYMBOL_DOWN, fanLevelDownCb);

    s_fanLevelLbl = lv_label_create(s_fanLevelRow);
    lv_obj_set_style_text_font(s_fanLevelLbl, &lv_font_montserrat_14, LV_PART_MAIN);
    lv_obj_set_style_text_color(s_fanLevelLbl, lv_color_white(), LV_PART_MAIN);
    lv_obj_set_style_text_align(s_fanLevelLbl, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
    lv_obj_set_size(s_fanLevelLbl, 70, 28);
    lv_obj_set_pos(s_fanLevelLbl, 38, 7);
    lv_label_set_text(s_fanLevelLbl, "5");

    makeBtn(s_fanLevelRow, 110, 0, 36, 28, LV_SYMBOL_UP, fanLevelUpCb);

    // ════════════════════════════════════════════════════════════════════
    // RIGHT PANEL — HOT WATER
    // Content width: W_R - 4 = 161 px  (2 px margin)
    // ════════════════════════════════════════════════════════════════════
    const int rx = X_R + 2;    // x=156
    const int rw = W_R - 4;    // 162 px

    makeSecLabel(s_scr, rx, Y_CONT + 2, t(TK::HOT_WATER));

    // 4 boiler buttons in a 2×2 grid
    // button width: (162 - 9) / 2 = 76 px,  gap = 9 px
    const int bw = (rw - 9) / 2;
    int bx[4] = {rx,      rx + bw + 9, rx,      rx + bw + 9};
    int by[4] = {Y_CONT + 20, Y_CONT + 20, Y_CONT + 62, Y_CONT + 62};
    for (int i = 0; i < BOILER_N; i++) {
        s_boilerBtn[i] = makeBtn(s_scr, bx[i], by[i], bw, 38,
                                  boilerLabel(i), boilerCb, (void*)(intptr_t)i);
    }

    // ── Solar data (left column) + Battery SOC (right column) ────────────
    // Layout: solar 106 px | 1 px sep | battery 54 px  (total = rw = 161 px + 1)
    // Solar column: y=104..175, battery column: y=104..175
    const int SC_W  = 106;               // solar column width
    const int BC_X  = rx + SC_W + 2;    // battery column x (~264)
    const int BC_W  = rw - SC_W - 2;    // battery column width (~54 px)
    // Battery pill icon (vertical): body 34×39, two nubs 5×4 above body
    const int BB_W  = 34;                        // body width
    const int BB_X  = BC_X + (BC_W - BB_W) / 2; // body left edge (centered)
    const int BB_Y  = Y_CONT + 129;             // body top (baseline Y+168, 5px gap from SOC label)
    s_battFillX = BB_X + 1;
    const int BB_H  = 39;                        // body height
    const int BF_IH = BB_H - 2;                 // fill inner height (37 px)

    // Section label — uppercase like HEATING/FAN/HOT_WATER
    makeSecLabel(s_scr, rx, Y_CONT + 104,
        currentLanguage() == Language::EN ? "SOLAR CHARGE" : "CARGA SOLAR");

    // Solar data: 3 rows × 14 px = 42 px, centered in 50 px below section label+3px gap
    // (section label h≈16, 3px margin → data area Y+123..Y+173, top pad 4px → Y+127)
    // State line — e.g. "Bulk" / "Float" / "--"
    s_solarStateLbl = lv_label_create(s_scr);
    lv_obj_set_style_text_font(s_solarStateLbl, &lv_font_montserrat_14, LV_PART_MAIN);
    lv_obj_set_style_text_color(s_solarStateLbl, lv_color_white(), LV_PART_MAIN);
    lv_obj_set_size(s_solarStateLbl, SC_W, 14);
    lv_obj_set_pos(s_solarStateLbl, rx, Y_CONT + 127);
    lv_label_set_long_mode(s_solarStateLbl, LV_LABEL_LONG_DOT);
    lv_label_set_text(s_solarStateLbl, "--");

    // Battery/current line — "12.6V 1.5A"
    s_solarBattLbl = lv_label_create(s_scr);
    lv_obj_set_style_text_font(s_solarBattLbl, &lv_font_montserrat_14, LV_PART_MAIN);
    lv_obj_set_style_text_color(s_solarBattLbl, lv_color_hex(0x88ccff), LV_PART_MAIN);
    lv_obj_set_size(s_solarBattLbl, SC_W, 14);
    lv_obj_set_pos(s_solarBattLbl, rx, Y_CONT + 141);
    lv_label_set_text(s_solarBattLbl, "--");

    // PV + kWh line — "120W 0.8kWh"
    s_solarPvLbl = lv_label_create(s_scr);
    lv_obj_set_style_text_font(s_solarPvLbl, &lv_font_montserrat_14, LV_PART_MAIN);
    lv_obj_set_style_text_color(s_solarPvLbl, lv_color_hex(0xffdd66), LV_PART_MAIN);
    lv_obj_set_size(s_solarPvLbl, SC_W, 14);
    lv_obj_set_pos(s_solarPvLbl, rx, Y_CONT + 155);
    lv_label_set_text(s_solarPvLbl, "--");

    // Vertical separator between solar and battery columns
    makeSep(s_scr, rx + SC_W + 1, Y_CONT + 104, 1, 69);

    // ── Battery column ────────────────────────────────────────────────────
    // SOC % label — centered in battery column
    s_battSocLbl = lv_label_create(s_scr);
    lv_obj_set_style_text_font(s_battSocLbl, &lv_font_montserrat_14, LV_PART_MAIN);
    lv_obj_set_style_text_color(s_battSocLbl, lv_color_white(), LV_PART_MAIN);
    lv_obj_set_style_text_align(s_battSocLbl, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
    lv_obj_set_size(s_battSocLbl, BC_W, 14);
    lv_obj_set_pos(s_battSocLbl, BC_X, Y_CONT + 106);
    lv_label_set_text(s_battSocLbl, "--");

    // Battery terminals (two nubs above body, left and right)
    auto makeBattNub = [&](int x) -> lv_obj_t* {
        lv_obj_t* n = lv_obj_create(s_scr);
        lv_obj_remove_style_all(n);
        lv_obj_set_size(n, 5, 4);
        lv_obj_set_pos(n, x, BB_Y - 4);
        lv_obj_set_style_bg_opa(n, LV_OPA_COVER, LV_PART_MAIN);
        lv_obj_set_style_bg_color(n, lv_color_hex(0x888888), LV_PART_MAIN);
        lv_obj_set_style_radius(n, 1, LV_PART_MAIN);
        lv_obj_clear_flag(n, (lv_obj_flag_t)LV_OBJ_FLAG_SCROLLABLE);
        return n;
    };
    s_battNub  = makeBattNub(BB_X + 3);               // left terminal
    s_battNub2 = makeBattNub(BB_X + BB_W - 5 - 3);   // right terminal

    // Battery body: border-only vertical rect 30×44 px
    s_battBody = lv_obj_create(s_scr);
    lv_obj_remove_style_all(s_battBody);
    lv_obj_set_size(s_battBody, BB_W, BB_H);
    lv_obj_set_pos(s_battBody, BB_X, BB_Y);
    lv_obj_set_style_bg_opa(s_battBody, LV_OPA_0, LV_PART_MAIN);
    lv_obj_set_style_border_color(s_battBody, lv_color_hex(0x888888), LV_PART_MAIN);
    lv_obj_set_style_border_width(s_battBody, 1, LV_PART_MAIN);
    lv_obj_set_style_radius(s_battBody, 2, LV_PART_MAIN);
    lv_obj_clear_flag(s_battBody, (lv_obj_flag_t)LV_OBJ_FLAG_SCROLLABLE);

    // Battery fill: bottom-anchored, height updated by cydUpdateBatt()
    s_battFill = lv_obj_create(s_scr);
    lv_obj_remove_style_all(s_battFill);
    lv_obj_set_size(s_battFill, BB_W - 2, 0);   // height = 0 until first update
    lv_obj_set_pos(s_battFill, BB_X + 1, BB_Y + 1 + BF_IH);  // starts at bottom
    lv_obj_set_style_bg_opa(s_battFill, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_set_style_bg_color(s_battFill, lv_color_hex(0x44bb44), LV_PART_MAIN);
    lv_obj_set_style_radius(s_battFill, 1, LV_PART_MAIN);
    lv_obj_clear_flag(s_battFill, (lv_obj_flag_t)LV_OBJ_FLAG_SCROLLABLE);

    // ── Energy dropdown — hidden on Combi D (no electrical option) ────────
    lv_obj_add_flag(makeSecLabel(s_scr, rx, Y_CONT + 108, t(TK::ENERGY)), LV_OBJ_FLAG_HIDDEN);

    s_energyDd = lv_dropdown_create(s_scr);
    lv_obj_set_pos(s_energyDd, rx, Y_CONT + 124);
    lv_obj_set_size(s_energyDd, rw, 28);
    lv_dropdown_set_options(s_energyDd,
        "Gas\n"
        "Gas + Elec. 850 W\n"
        "Gas + Elec. 1700 W\n"
        "Elec. 850 W\n"
        "Elec. 1700 W");
    lv_dropdown_set_selected(s_energyDd, (uint16_t)s_energyMode);

    lv_obj_set_style_bg_color(s_energyDd,     lv_color_hex(C_BTN_OFF), LV_PART_MAIN);
    lv_obj_set_style_text_color(s_energyDd,   lv_color_white(),         LV_PART_MAIN);
    lv_obj_set_style_border_color(s_energyDd, lv_color_hex(C_SEP),      LV_PART_MAIN);
    lv_obj_set_style_border_width(s_energyDd, 1,                         LV_PART_MAIN);
    lv_obj_set_style_text_font(s_energyDd,    &lv_font_montserrat_14,    LV_PART_MAIN);

    lv_obj_t* ddList = lv_dropdown_get_list(s_energyDd);
    lv_obj_set_style_bg_color(ddList,     lv_color_hex(C_BTN_OFF), LV_PART_MAIN);
    lv_obj_set_style_text_color(ddList,   lv_color_white(),         LV_PART_MAIN);
    lv_obj_set_style_border_color(ddList, lv_color_hex(C_SEP),      LV_PART_MAIN);
    lv_obj_set_style_text_font(ddList,    &lv_font_montserrat_14,    LV_PART_MAIN);

    lv_obj_add_event_cb(s_energyDd, energyDdCb, LV_EVENT_VALUE_CHANGED, nullptr);
    lv_obj_add_flag(s_energyDd, LV_OBJ_FLAG_HIDDEN);

    // ── Status bar ────────────────────────────────────────────────────────
    s_statusLbl = lv_label_create(s_scr);
    lv_obj_set_style_text_font(s_statusLbl, &lv_font_montserrat_14, LV_PART_MAIN);
    lv_obj_set_style_text_color(s_statusLbl, lv_color_hex(C_WIFI_OK), LV_PART_MAIN);
    lv_label_set_text(s_statusLbl, t(TK::STATUS_INIT));
    lv_obj_align(s_statusLbl, LV_ALIGN_BOTTOM_LEFT, 5, -18);

    s_ipLbl = lv_label_create(s_scr);
    lv_obj_set_style_text_font(s_ipLbl, &lv_font_montserrat_12, LV_PART_MAIN);
    lv_obj_set_style_text_color(s_ipLbl, lv_color_hex(0x88aaff), LV_PART_MAIN);
    lv_label_set_text(s_ipLbl, "");
    lv_obj_set_width(s_ipLbl, 310);
    lv_label_set_long_mode(s_ipLbl, LV_LABEL_LONG_DOT);
    lv_obj_align(s_ipLbl, LV_ALIGN_BOTTOM_LEFT, 5, -2);

    refreshControls();
    placeLogoInStatusBar(s_scr);
}

// ═══════════════════════════════════════════════════════════════════════════
// cydUpdateSolar — refresh solar data labels (call under LVGL mutex)
// ═══════════════════════════════════════════════════════════════════════════
static const char* solarStateName(uint8_t s) {
    bool es = (currentLanguage() == Language::ES);
    switch (s) {
        case   0: return es ? "Apagado"      : "Off";
        case   2: return es ? "Fallo"        : "Fault";
        case   3: return es ? "Carga inicial": "Bulk";
        case   4: return es ? "Absorcion"     : "Absorb";
        case   5: return es ? "Flotacion"     : "Float";
        case   7: return es ? "Ecualiz."     : "Equalize";
        case 245: return es ? "Iniciando"    : "Starting";
        case 247: return es ? "Auto-ec."     : "Auto-eq";
        case 252: return es ? "Ctrl. ext."   : "Ext ctrl";
        default:  return "?";
    }
}

void cydUpdateSolar(const CydSolarData& d) {
    if (!s_solarStateLbl) return;

    char buf[32];

    if (!d.configured) {
        lv_label_set_text(s_solarStateLbl, t(TK::SOLAR_NO_DATA));
        lv_label_set_text(s_solarBattLbl,  "");
        lv_label_set_text(s_solarPvLbl,    "");
        return;
    }

    // Stale data after 2 minutes → show "--"
    bool fresh = d.valid && d.ageMs < 120000;

    if (!fresh) {
        lv_label_set_text(s_solarStateLbl, "--");
        lv_label_set_text(s_solarBattLbl,  "--");
        lv_label_set_text(s_solarPvLbl,    "--");
        return;
    }

    // State line: "Bulk" (+ " E01" if error)
    if (d.errCode != 0) {
        snprintf(buf, sizeof(buf), "%s E%02d", solarStateName(d.state), d.errCode);
    } else {
        snprintf(buf, sizeof(buf), "%s", solarStateName(d.state));
    }
    lv_label_set_text(s_solarStateLbl, buf);

    // Battery line: "12.6V 1.5A"  (single space — narrower column)
    snprintf(buf, sizeof(buf), "%.1fV %.1fA", d.battV, d.battA);
    lv_label_set_text(s_solarBattLbl, buf);

    // PV line: "120W 0.8kWh"
    snprintf(buf, sizeof(buf), "%.0fW %.1fkWh", d.pvW, d.kWhToday);
    lv_label_set_text(s_solarPvLbl, buf);
}

// ═══════════════════════════════════════════════════════════════════════════
// cydUpdateBatt — refresh battery SOC widget (call under LVGL mutex)
// ═══════════════════════════════════════════════════════════════════════════
void cydUpdateBatt(const CydBattData& d) {
    if (!s_battSocLbl) return;

    // These must match the static constants in buildMainUI()
    static const int BB_Y  = Y_CONT + 129;
    static const int BF_IH = 37;   // fill inner height

    bool fresh = d.configured && d.valid && d.ageMs < 120000;

    if (!fresh) {
        lv_label_set_text(s_battSocLbl, "--");
        lv_obj_set_height(s_battFill, 0);
        return;
    }

    char buf[8];
    snprintf(buf, sizeof(buf), "%d%%", d.soc);
    lv_label_set_text(s_battSocLbl, buf);

    // Fill is bottom-anchored: taller = more charge
    int fillH = (int)d.soc * BF_IH / 100;
    if (fillH < 0)    fillH = 0;
    if (fillH > BF_IH) fillH = BF_IH;
    lv_obj_set_size(s_battFill, 32, fillH);   // 32 = body width (34) - 2 borders
    lv_obj_set_pos(s_battFill, s_battFillX,
                               BB_Y + 1 + (BF_IH - fillH));

    // Color: green ≥50%, amber 20–49%, red <20% — only fill changes color
    uint32_t color = (d.soc >= 50) ? 0x44bb44u
                   : (d.soc >= 20) ? 0xffbb00u
                                   : 0xff3333u;
    lv_obj_set_style_bg_color(s_battFill, lv_color_hex(color), LV_PART_MAIN);
}

// ═══════════════════════════════════════════════════════════════════════════
// cydRebuildUI — tear down and recreate all main-screen widgets
// ═══════════════════════════════════════════════════════════════════════════
void cydRebuildUI() {
    if (!s_scr) return;
    // Null out error modal handle before lv_obj_clean deletes it
    s_errorModal   = nullptr;
    s_lastErrClass = 0;
    s_lastErrCode  = 0;
    s_errAcked     = false;
    // Null widget handles (pointers become dangling after lv_obj_clean)
    s_ambLbl = s_aguaLbl = s_fireLbl = s_extLbl = nullptr;
    s_wifiDot = s_linDot = nullptr;
    s_heatBtn = s_heatBtnLbl = nullptr;
    s_spRow = s_spLbl = nullptr;
    s_fanHeatingRow = s_fanOffRow = s_fanLevelRow = nullptr;
    for (int i = 0; i < FAN_N;    i++) s_fanBtn[i]    = nullptr;
    for (int i = 0; i < BOILER_N; i++) s_boilerBtn[i] = nullptr;
    s_fanOnBtn = s_fanOffBtn = s_fanLevelLbl = nullptr;
    s_energyDd = s_statusLbl = s_ipLbl = nullptr;
    s_solarStateLbl = s_solarBattLbl = s_solarPvLbl = nullptr;
    s_battSocLbl = s_battBody = s_battFill = s_battNub = s_battNub2 = nullptr;

    lv_obj_clean(s_scr);   // delete all children
    buildMainUI();
}

// ═══════════════════════════════════════════════════════════════════════════
// cydFreeMainUI — free all main-screen widgets without rebuilding.
// Call before entering a blocking setup screen that needs LVGL heap room
// (the keyboard widget alone is ~16 KB). Follow with cydRebuildUI() on exit.
// Must be called under the LVGL mutex.
// ═══════════════════════════════════════════════════════════════════════════
void cydFreeMainUI() {
    if (!s_scr) return;
    s_errorModal   = nullptr;
    s_lastErrClass = 0;
    s_lastErrCode  = 0;
    s_errAcked     = false;
    s_ambLbl = s_aguaLbl = s_fireLbl = s_extLbl = nullptr;
    s_wifiDot = s_linDot = nullptr;
    s_heatBtn = s_heatBtnLbl = nullptr;
    s_spRow = s_spLbl = nullptr;
    s_fanHeatingRow = s_fanOffRow = s_fanLevelRow = nullptr;
    for (int i = 0; i < FAN_N;    i++) s_fanBtn[i]    = nullptr;
    for (int i = 0; i < BOILER_N; i++) s_boilerBtn[i] = nullptr;
    s_fanOnBtn = s_fanOffBtn = s_fanLevelLbl = nullptr;
    s_energyDd = s_statusLbl = s_ipLbl = nullptr;
    s_solarStateLbl = s_solarBattLbl = s_solarPvLbl = nullptr;
    s_battSocLbl = s_battBody = s_battFill = s_battNub = s_battNub2 = nullptr;
    lv_obj_clean(s_scr);
}

// ═══════════════════════════════════════════════════════════════════════════
// cydDisplayInit
// ═══════════════════════════════════════════════════════════════════════════
void cydDisplayInit(TTempSetting*   roomSetpoint,
                    TBoilerSetting* waterSetpoint,
                    TOnOffSetting*  heatingOn,
                    TFanSetting*    fanMode) {
    s_roomSp  = roomSetpoint;
    s_waterSp = waterSetpoint;
    s_heatOn  = heatingOn;
    s_fanMode = fanMode;

    loadTimeoutIdx();
    loadLanguage();

    showSplash(2000);

    // Language selection on first boot (no language stored in NVS yet)
    if (!isLanguageSet()) showLangSelectBlocking();

    // ── Main screen ──────────────────────────────────────────────────────
    s_scr = lv_obj_create(NULL);
    lv_obj_remove_style_all(s_scr);
    lv_obj_set_style_bg_color(s_scr, lv_color_hex(C_BG), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(s_scr, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_clear_flag(s_scr, (lv_obj_flag_t)LV_OBJ_FLAG_SCROLLABLE);

    buildMainUI();          // populate before loading to avoid blank-screen flash
    lv_screen_load(s_scr);

    lv_mem_monitor_t mon;
    lv_mem_monitor(&mon);
    Serial.printf("[lvgl] pool used=%u/%u free=%u frag=%u%%\n",
        (unsigned)mon.total_size - mon.free_size,
        (unsigned)mon.total_size,
        (unsigned)mon.free_size,
        (unsigned)mon.frag_pct);

    // Backlight fade task (Core 1, low priority)
    xTaskCreatePinnedToCore(backlightTask, "bckl", 1536, nullptr, 1, nullptr, 1);
}

// ═══════════════════════════════════════════════════════════════════════════
// cydDisplayUpdate  — called every loop() iteration
// ═══════════════════════════════════════════════════════════════════════════
void cydDisplayUpdate(bool wifiok, bool trumaok,
                      bool truma_reset, bool inota,
                      float roomTemp, float waterTemp, bool waterHeating,
                      float extTemp, uint8_t errClass, uint8_t errCode) {

    // ── Auto screen-off ─────────────────────────────────────────────────
    // Three stages: 100% → 30% dim warning (5 s before) → off.
    // Any touch resets lv_display_get_inactive_time(), which undoes the dim.
    {
        uint32_t to       = TIMEOUT_MS[s_timeoutIdx];
        uint32_t inactive = lv_display_get_inactive_time(NULL);

        if (to > 0 && !s_screenOff) {
            if (inactive >= to) {
                blFadeTo(0.0f);
                s_screenOff    = true;
                s_screenDimmed = false;
                if (!s_wakeOverlay) {
                    // Transparent overlay on lv_layer_top — captures the first
                    // touch and re-lights the screen without activating controls below.
                    s_wakeOverlay = lv_obj_create(lv_layer_top());
                    lv_obj_remove_style_all(s_wakeOverlay);
                    lv_obj_set_size(s_wakeOverlay, 320, 240);
                    lv_obj_set_pos(s_wakeOverlay, 0, 0);
                    lv_obj_set_style_bg_opa(s_wakeOverlay, LV_OPA_TRANSP, LV_PART_MAIN);
                    lv_obj_add_event_cb(s_wakeOverlay, wakeCb, LV_EVENT_PRESSED, nullptr);
                }
            } else if (inactive + 5000 >= to) {
                if (!s_screenDimmed) { blFadeTo(0.3f); s_screenDimmed = true; }
            } else {
                if (s_screenDimmed) { blFadeTo(1.0f); s_screenDimmed = false; }
            }
        }
    }

    // ── Tint (boiler/water) and fire (heating) indicators ────────────────
    {
        bool blinkPhase = (millis() % 1000) < 500;
        if (s_aguaLbl) {
            bool   boilerOn  = s_waterSp && (s_waterSp->getStringValue() != "off");
            double wSetpoint = s_waterSp ? s_waterSp->getFloatValue() : 0.0;
            // Override the protocol flag during cooldown: flag stays set after
            // the burner stops, but temperature comparison is authoritative.
            bool   wAtTemp   = boilerOn && (waterTemp > 0.0f) && ((double)waterTemp >= wSetpoint - 1.0);
            lv_color_t c;
            lv_opa_t   opa;
            if (!boilerOn)                     { c = lv_color_hex(0xaaccff); opa = LV_OPA_20; } // off: dim blue
            else if (!waterHeating || wAtTemp) { c = lv_color_hex(0xaaccff); opa = LV_OPA_COVER; } // at temp: solid blue
            else if (blinkPhase)               { c = lv_color_hex(0xaaccff); opa = LV_OPA_COVER; } // heating: visible phase
            else                               { c = lv_color_hex(C_TOPBAR); opa = LV_OPA_COVER; } // heating: dark phase
            lv_obj_set_style_text_color(s_aguaLbl, c, LV_PART_MAIN);
            lv_obj_set_style_text_opa(s_aguaLbl, opa, LV_PART_MAIN);
        }
        if (s_fireLbl) {
            bool  heatOn     = s_heatOn && (s_heatOn->getIntValue() != 0);
            float sp         = (s_roomSp && heatOn) ? s_roomSp->getFloatValue() : 0.0f;
            bool  heatDemand = heatOn && trumaok && (roomTemp > -200.0f) && (roomTemp < sp - 0.3f);
            lv_color_t c;
            lv_opa_t   opa;
            if (!heatOn)      { c = lv_color_hex(0xaaccff); opa = LV_OPA_20; } // off: dim blue
            else if (!heatDemand) { c = lv_color_hex(0xff8844); opa = LV_OPA_COVER; } // at temp: solid orange
            else if (blinkPhase)  { c = lv_color_hex(0xff8844); opa = LV_OPA_COVER; } // heating: visible phase
            else                  { c = lv_color_hex(C_TOPBAR);  opa = LV_OPA_COVER; } // heating: dark phase
            lv_obj_set_style_text_color(s_fireLbl, c, LV_PART_MAIN);
            lv_obj_set_style_text_opa(s_fireLbl, opa, LV_PART_MAIN);
        }
    }

    // ── Indoor temperature label ─────────────────────────────────────────
    if (s_ambLbl) {
        char buf[32];
        if (trumaok && roomTemp > -200.0f)
            snprintf(buf, sizeof(buf), MY_SYMBOL_THERMOMETER " %.1f \xc2\xb0""C", roomTemp);
        else
            strcpy(buf, MY_SYMBOL_THERMOMETER " -- \xc2\xb0""C");
        lv_label_set_text(s_ambLbl, buf);
    }

    // ── Outdoor temperature (AM2301) ─────────────────────────────────────
    if (s_extLbl) {
        char buf[28];
        if (extTemp > -200.0f)
            snprintf(buf, sizeof(buf), MY_SYMBOL_THERM_EXT " " MY_SYMBOL_CHEVRON_R " %.1f\xc2\xb0""C", extTemp);
        else
            strcpy(buf, MY_SYMBOL_THERM_EXT " " MY_SYMBOL_CHEVRON_R " --\xc2\xb0""C");
        lv_label_set_text(s_extLbl, buf);
    }

    // ── WiFi icon ────────────────────────────────────────────────────────
    static bool s_everConnected = false;
    static bool s_lastWifiOk = false;
    if (wifiok != s_lastWifiOk) {
        s_lastWifiOk = wifiok;
        Serial.printf("[wifi] wifiok changed: %s  heap=%u\n",
                      wifiok ? "true" : "false", ESP.getFreeHeap());
    }
    if (wifiok) s_everConnected = true;
    if (s_wifiDot) {
        lv_color_t c = lv_color_hex(wifiok          ? C_WIFI_OK   :
                                     s_everConnected ? C_WIFI_NO   :
                                                       C_WIFI_CONN);
        lv_obj_set_style_text_color(s_wifiDot, c, LV_PART_MAIN);
    }

    // ── LIN bus icon ─────────────────────────────────────────────────────
    if (s_linDot)
        lv_obj_set_style_text_color(s_linDot,
            lv_color_hex(trumaok ? C_WIFI_OK : C_WIFI_NO), LV_PART_MAIN);

    // ── SSID / IP address ────────────────────────────────────────────────
    if (s_ipLbl) {
        if (wifiok) {
            char buf[64];
            snprintf(buf, sizeof(buf), "%s  %s", WiFi.SSID().c_str(), WiFi.localIP().toString().c_str());
            lv_label_set_text(s_ipLbl, buf);
        } else {
            lv_label_set_text(s_ipLbl, "");
        }
    }

    // ── Status message ───────────────────────────────────────────────────
    static char s_errBuf[48];
    const char* msg  = "";
    uint32_t    msgC = C_WIFI_OK;

    if (inota) {
        msg = t(TK::STATUS_OTA);          msgC = 0xffd700;
    } else if (!wifiok) {
        auto ws = WiFi.status();
        if (ws == WL_DISCONNECTED || ws == WL_IDLE_STATUS) {
            msg = t(TK::STATUS_WIFI_CONN); msgC = C_WIFI_CONN;
        } else {
            msg = t(TK::STATUS_NO_WIFI);   msgC = C_WIFI_NO;
        }
    } else if (!trumaok) {
        // prepend a warning symbol; snprintf into the shared error buffer
        snprintf(s_errBuf, sizeof(s_errBuf), "%s %s", LV_SYMBOL_WARNING, t(TK::STATUS_NO_LIN));
        msg  = s_errBuf;
        msgC = C_WIFI_NO;
    } else if (errCode != 0) {
        TK errLblKey;
        if (errClass == 1 || errClass == 2) { errLblKey = TK::WARN_LBL;   msgC = C_WARN;       }
        else if (errClass == 40)             { errLblKey = TK::LOCKED_LBL; msgC = C_ERR_LOCKED; }
        else                                 { errLblKey = TK::ERROR_LBL;  msgC = C_WIFI_NO;    }
        snprintf(s_errBuf, sizeof(s_errBuf), "%s %s  Cl.%02Xh/Cod.%d",
                 LV_SYMBOL_WARNING, t(errLblKey), errClass, errCode);
        msg = s_errBuf;
    }

    if (s_statusLbl) {
        lv_label_set_text(s_statusLbl, msg);
        lv_obj_set_style_text_color(s_statusLbl, lv_color_hex(msgC), LV_PART_MAIN);
    }

    // ── Truma error modal ────────────────────────────────────────────────
    if (errClass != s_lastErrClass || errCode != s_lastErrCode) {
        s_lastErrClass = errClass;
        s_lastErrCode  = errCode;
        s_errAcked     = false;
        if (s_errorModal) { lv_obj_delete(s_errorModal); s_errorModal = nullptr; }
    }
    if (errCode != 0 && !s_errAcked && !s_errorModal) showErrorModal(errClass, errCode);

    // ── Re-sync controls (may have changed via external MQTT/WS) ─────────
    refreshControls();
}

#endif // CYD
